package com.studynotes.app.testutil

import android.content.Context
import androidx.test.platform.app.InstrumentationRegistry
import java.io.File

/**
 * Test documents from testdata/ (bundled as androidTest assets, regenerated by
 * tools/make_fixtures.py). They are copied into the app's cache dir so the code under test reads
 * real files, exactly as it does in the app.
 */
object Fixtures {
    const val LECTURE_NOTES = "Biology Lecture Notes.pdf"
    const val ANNOTATED_ELSEWHERE = "Annotated Elsewhere.pdf"
    const val SCANNED = "Scanned Handout.pdf"
    const val TEXTBOOK = "Big Textbook (300 pages).pdf"
    const val PASSWORD = "Password Protected.pdf"
    const val STUDY_GUIDE_DOCX = "Cell Biology Study Guide.docx"
    const val MINIMAL_DOCX = "Minimal.docx"
    const val CORRUPT_DOCX = "Corrupt.docx"

    /** "Biology Lecture Notes.pdf" page indices (0-based) with special geometry. */
    const val PAGE_PLAIN = 0
    const val PAGE_ROTATED_90 = 4
    const val PAGE_CROPPED = 5
    const val PAGE_LANDSCAPE = 6

    val targetContext: Context get() = InstrumentationRegistry.getInstrumentation().targetContext

    /** A fresh, empty directory under the app's cache dir. */
    fun scratchDir(name: String): File {
        val dir = File(targetContext.cacheDir, "androidTest/$name")
        dir.deleteRecursively()
        check(dir.mkdirs()) { "Could not create $dir" }
        return dir
    }

    /** Copies asset [name] into [dir] (default: a shared fixtures dir) and returns the copy. */
    fun copy(name: String, dir: File = File(targetContext.cacheDir, "androidTest/fixtures"), asName: String = name): File {
        dir.mkdirs()
        val out = File(dir, asName)
        InstrumentationRegistry.getInstrumentation().context.assets.open(name).use { input ->
            out.outputStream().use { input.copyTo(it) }
        }
        return out
    }

    fun bytes(name: String): ByteArray =
        InstrumentationRegistry.getInstrumentation().context.assets.open(name).use { it.readBytes() }
}
